"use client";
import { controlStyles } from "@/components/ui/kalos-styles";
import * as React from "react";
import { Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/kalos-base-button";
export function KalosButton({
  loading = false,
  variant = "default",
  size = "default",
  disabled,
  children,
  ...props
}: React.ComponentProps<typeof Button> & { loading?: boolean }) {
  return (
    <Button
      {...props}
      variant={variant}
      size={size}
      className={cn(
        controlStyles.button,
        variant === "default" && controlStyles.buttonSolid,
        variant === "destructive" && controlStyles.buttonDanger,
        (variant === "secondary" || variant === "outline") && controlStyles.buttonSurface,
        variant === "ghost" && controlStyles.buttonGhost,
        props.className,
      )}
      disabled={disabled || loading}
      aria-busy={loading || undefined}
    >
      {loading ? (
        <Loader2 data-icon="inline-start" className="animate-spin" />
      ) : null}
      {children}
    </Button>
  );
}

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center rounded-[6px] border border-transparent bg-clip-padding text-[13px] font-medium whitespace-nowrap transition-all duration-150 outline-none select-none active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        outline:
          "border-input/50 bg-card shadow-[0_1px_2px_color-mix(in_srgb,var(--foreground)_5%,transparent)] hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          "border-input/50 bg-card text-card-foreground shadow-[0_1px_2px_color-mix(in_srgb,var(--foreground)_5%,transparent)] hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50",
        destructive:
          "bg-destructive/10 text-destructive hover:bg-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 ",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-8 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        xs: "h-6 gap-1 rounded-[min(var(--radius-md),10px)] px-2 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-7 gap-1 rounded-[min(var(--radius-md),12px)] px-2.5 text-[0.8rem] in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-9 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        icon: "size-8",
        "icon-xs":
          "size-6 rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-lg [&_svg:not([class*='size-'])]:size-3",
        "icon-sm":
          "size-7 rounded-[min(var(--radius-md),12px)] in-data-[slot=button-group]:rounded-lg",
        "icon-lg": "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

function Button({
  className,
  variant = "default",
  size = "default",
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };

"use client";

export { KalosCommandMenu } from "@/components/ui/kalos-command-menu-panel";
export type { KalosCommandItem, KalosCommandGroup, KalosCommandMenuProps } from "@/components/ui/kalos-command-menu-panel";

"use client";

import { useCallback, useEffect, useRef } from "react";

export const slidingHighlightClasses = "relative isolate before:pointer-events-none before:absolute before:left-[var(--kalos-highlight-x,0px)] before:top-[var(--kalos-highlight-y,0px)] before:z-0 before:h-[var(--kalos-highlight-height,0px)] before:w-[var(--kalos-highlight-width,0px)] before:rounded-[5px] before:bg-accent before:opacity-[var(--kalos-highlight-opacity,0)] before:transition-[left,top,width,height,opacity] before:duration-200 before:ease-[cubic-bezier(.2,.8,.2,1)] before:content-[''] [&_[role=option]]:relative [&_[role=option]]:z-10 [&_[role=option]]:bg-transparent!";

/** A single background follows the library's own focused/selected item. */
export function useSlidingHighlight(selector: string, activeSelector: string, followPointer = false) {
  const cleanup = useRef<(() => void) | null>(null);
  useEffect(() => () => cleanup.current?.(), []);
  return useCallback((node: HTMLElement | null) => {
    cleanup.current?.();
    cleanup.current = null;
    if (!node) return;
    let frame = 0;
    const position = (item: HTMLElement | null) => {
      if (!item) { node.style.setProperty("--kalos-highlight-opacity", "0"); return; }
      if (!node.contains(item) || item.matches('[aria-disabled="true"], [data-disabled]')) return;
      const root = node.getBoundingClientRect();
      const target = item.getBoundingClientRect();
      const scaleX = node.offsetWidth ? root.width / node.offsetWidth : 1;
      const scaleY = node.offsetHeight ? root.height / node.offsetHeight : 1;
      node.style.setProperty("--kalos-highlight-x", `${(target.left - root.left) / scaleX + node.scrollLeft - node.clientLeft}px`);
      node.style.setProperty("--kalos-highlight-y", `${(target.top - root.top) / scaleY + node.scrollTop - node.clientTop}px`);
      node.style.setProperty("--kalos-highlight-width", `${target.width / scaleX}px`);
      node.style.setProperty("--kalos-highlight-height", `${target.height / scaleY}px`);
      node.style.setProperty("--kalos-highlight-opacity", "1");
    };
    const update = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(() => position(activeSelector.split(",").map(query => node.querySelector<HTMLElement>(query.trim())).find(Boolean) ?? null));
    };
    const pointer = (event: Event) => {
      if (event.target instanceof Element) position(event.target.closest<HTMLElement>(selector));
    };
    const observer = new MutationObserver(update);
    observer.observe(node, { subtree: true, childList: true, attributes: true, attributeFilter: ["data-highlighted", "data-focused", "data-state", "aria-selected", "aria-activedescendant"] });
    const resize = new ResizeObserver(update);
    resize.observe(node);
    node.addEventListener("scroll", update, true);
    if (followPointer) {
      node.addEventListener("pointermove", pointer);
      node.addEventListener("focusin", pointer);
    }
    update();
    cleanup.current = () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      resize.disconnect();
      node.removeEventListener("scroll", update, true);
      node.removeEventListener("pointermove", pointer);
      node.removeEventListener("focusin", pointer);
    };
  }, [selector, activeSelector, followPointer]);
}

"use client";

import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import { Search } from "lucide-react";
import { cn } from "@/lib/utils";
import { controlStyles } from "@/components/ui/kalos-styles";
import { slidingHighlightClasses, useSlidingHighlight } from "@/components/ui/kalos-highlight";

export type KalosCommandItem = { value: string; label: string; description?: ReactNode; icon?: ReactNode; keywords?: string; disabled?: boolean };
export type KalosCommandGroup = { label: string; items: KalosCommandItem[] };
export type KalosCommandMenuProps = {
  groups: KalosCommandGroup[];
  label?: string;
  placeholder?: string;
  query?: string;
  defaultQuery?: string;
  onQueryChange?: (query: string) => void;
  onRun?: (value: string) => void;
  onClose?: () => void;
  filter?: boolean;
  autoFocus?: boolean;
  emptyMessage?: string;
  className?: string;
};

export function KalosCommandMenu({ groups, label = "命令菜单", placeholder = "搜索命令…", query, defaultQuery = "", onQueryChange, onRun, onClose, filter = true, autoFocus = false, emptyMessage = "没有找到匹配的内容", className }: KalosCommandMenuProps) {
  const [internalQuery, setInternalQuery] = useState(defaultQuery);
  const [index, setIndex] = useState(0);
  const input = useRef<HTMLInputElement>(null);
  const value = query ?? internalQuery;
  const listId = useId();
  const words = value.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
  const visible = groups.map(group => ({ ...group, items: group.items.filter(item => !filter || words.every(word => `${item.label} ${typeof item.description === "string" ? item.description : ""} ${item.keywords ?? ""}`.toLocaleLowerCase().includes(word))) })).filter(group => group.items.length);
  const options = visible.flatMap(group => group.items).filter(item => !item.disabled);
  const active = options.length ? Math.min(index, options.length - 1) : -1;
  const activeItem = options[active];
  const activeId = activeItem ? `${listId}-${options.indexOf(activeItem)}` : undefined;
  const highlight = useSlidingHighlight('[role="option"]', '[role="option"][aria-selected="true"]', true);
  useEffect(() => {
    if (activeId && document.activeElement === input.current) document.getElementById(activeId)?.scrollIntoView({ block: "nearest" });
  }, [activeId, value]);
  const changeQuery = (next: string) => {
    if (query === undefined) setInternalQuery(next);
    setIndex(0);
    onQueryChange?.(next);
  };
  return <div className={cn(controlStyles.commandMenu, className)}>
    <label className={controlStyles.commandSearch}>
      <Search aria-hidden="true" />
      <input
        ref={input}
        role="combobox" aria-label={label} aria-expanded="true" aria-controls={listId} aria-activedescendant={activeId} aria-autocomplete="list"
        autoComplete="off" autoFocus={autoFocus} className={controlStyles.commandInput} placeholder={placeholder} value={value}
        onChange={event => changeQuery(event.target.value)}
        onKeyDown={event => {
          if (event.nativeEvent.isComposing) return;
          if (["ArrowDown", "ArrowUp"].includes(event.key)) {
            event.preventDefault();
            if (options.length) setIndex((active + (event.key === "ArrowDown" ? 1 : -1) + options.length) % options.length);
          } else if ((event.ctrlKey || event.metaKey) && ["Home", "End"].includes(event.key)) {
            event.preventDefault(); setIndex(event.key === "Home" ? 0 : Math.max(0, options.length - 1));
          } else if (event.key === "Tab" && options.length) {
            event.preventDefault();
            const navigable = visible.filter(group => group.items.some(item => !item.disabled));
            const groupIndex = navigable.findIndex(group => group.items.includes(activeItem));
            const next = navigable[(groupIndex + (event.shiftKey ? -1 : 1) + navigable.length) % navigable.length].items.find(item => !item.disabled)!;
            setIndex(options.indexOf(next));
          } else if (event.key === "Enter" && activeItem) {
            event.preventDefault(); onRun?.(activeItem.value);
          } else if (event.key === "Escape") {
            event.preventDefault(); event.stopPropagation();
            if (value) changeQuery(""); else onClose?.();
          }
        }}
      />
      <kbd aria-hidden="true" className={controlStyles.commandKey}>↵</kbd>
    </label>
    <div ref={highlight} id={listId} role="listbox" aria-label={`${label}结果`} className={cn(slidingHighlightClasses, controlStyles.commandList)}>
      {visible.map(group => <div key={group.label} role="group" aria-label={group.label}>
        <div className={controlStyles.commandGroup} aria-hidden="true">{group.label}</div>
        {group.items.map(item => {
          const itemIndex = options.indexOf(item);
          const selected = itemIndex >= 0 && active === itemIndex;
          return <button
            key={item.value} id={itemIndex < 0 ? undefined : `${listId}-${itemIndex}`} type="button" role="option" aria-selected={selected} disabled={item.disabled} data-disabled={item.disabled || undefined}
            tabIndex={-1} className={controlStyles.commandItem}
            onPointerMove={() => { if (!item.disabled) setIndex(itemIndex); }}
            onMouseDown={event => event.preventDefault()}
            onClick={() => onRun?.(item.value)}
          >{item.icon ? <span className={controlStyles.commandIcon}>{item.icon}</span> : null}<span className={controlStyles.commandItemText}><span className={controlStyles.commandTitle}>{item.label}</span>{item.description ? <span className={controlStyles.commandDescription}>{item.description}</span> : null}</span></button>;
        })}
      </div>)}
      {visible.length === 0 ? <p className="px-3 py-8 text-center text-[13px] text-muted-foreground" role="status">{emptyMessage}</p> : null}
    </div>
    <div className={controlStyles.commandFooter} aria-hidden="true">
      <span><kbd className={controlStyles.commandKey}>↑</kbd><kbd className={controlStyles.commandKey}>↓</kbd>选择</span>
      <span><kbd className={controlStyles.commandKey}>Tab</kbd>切换分组</span>
      <span><kbd className={controlStyles.commandKey}>↵</kbd>执行</span>
      <span><kbd className={controlStyles.commandKey}>esc</kbd>清空 / 关闭</span>
    </div>
    <span className="sr-only" role="status">{options.length} 个可用结果</span>
  </div>;
}

"use client";

import { Button } from "@/components/ui/kalos-base-button";
import { Popover, PopoverTrigger, PopoverContent } from "@/components/ui/kalos-base-popover";
import { controlStyles } from "@/components/ui/kalos-styles";
import { KalosPopoverMenu, usePopoverState, type KalosPopoverProps } from "@/components/ui/kalos-popover-menu";

export function KalosPopover(props: KalosPopoverProps) {
  const { trigger, label = trigger, items = [], children, onAction, align = "start", disabled } = props;
  const [open, setOpen] = usePopoverState(props);
  return <Popover open={open} onOpenChange={setOpen}>
    <PopoverTrigger render={<Button variant="outline" disabled={disabled} className={`${controlStyles.button} ${controlStyles.buttonSurface}`} />}>{trigger}</PopoverTrigger>
    <PopoverContent align={align} aria-label={label}>
      {children ?? <KalosPopoverMenu label={label} items={items} onAction={value => { setOpen(false); onAction?.(value); }} />}
    </PopoverContent>
  </Popover>;
}

"use client";

import { Popover as Primitive } from "@base-ui/react/popover";
import { cn } from "@/lib/utils";
import { controlStyles } from "@/components/ui/kalos-styles";

export const Popover = Primitive.Root;
export const PopoverTrigger = Primitive.Trigger;
export function PopoverContent({ align = "start", className, ...props }: Primitive.Popup.Props & { align?: "start" | "center" | "end" }) {
  return <Primitive.Portal>
    <Primitive.Positioner sideOffset={8} align={align} className="z-50">
      <Primitive.Popup {...props} data-slot="popover-content" className={cn(controlStyles.popover, "origin-[var(--transform-origin)] transition-[opacity,transform] duration-150 data-starting-style:scale-95 data-starting-style:opacity-0 data-ending-style:scale-95 data-ending-style:opacity-0", className)} />
    </Primitive.Positioner>
  </Primitive.Portal>;
}

"use client";

import { useState, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { controlStyles } from "@/components/ui/kalos-styles";
import { slidingHighlightClasses, useSlidingHighlight } from "@/components/ui/kalos-highlight";

export type KalosPopoverItem = { value: string; label: string; disabled?: boolean };
export type KalosPopoverProps = {
  trigger: string;
  label?: string;
  items?: KalosPopoverItem[];
  children?: ReactNode;
  onAction?: (value: string) => void;
  align?: "start" | "center" | "end";
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  disabled?: boolean;
};

export function usePopoverState({ open, defaultOpen = false, onOpenChange }: KalosPopoverProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  return [open ?? internalOpen, (next: boolean) => {
    if (open === undefined) setInternalOpen(next);
    onOpenChange?.(next);
  }] as const;
}

export function KalosPopoverMenu({ label, items, onAction }: {
  label: string;
  items: KalosPopoverItem[];
  onAction: (value: string) => void;
}) {
  const highlight = useSlidingHighlight('[role="menuitem"]', '[role="menuitem"]:focus', true);
  return <div
    ref={highlight}
    role="menu"
    aria-label={label}
    className={cn(slidingHighlightClasses, controlStyles.popoverList)}
    onKeyDown={event => {
      if (!["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
      const options = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="menuitem"]:not(:disabled)')];
      if (!options.length) return;
      event.preventDefault();
      const index = options.indexOf(document.activeElement as HTMLButtonElement);
      const next = event.key === "Home" ? 0 : event.key === "End" ? options.length - 1 : (index + (event.key === "ArrowDown" ? 1 : -1) + options.length) % options.length;
      options[next].focus();
    }}
  >{items.map(item => <button
    key={item.value}
    type="button"
    role="menuitem"
    disabled={item.disabled}
    data-disabled={item.disabled || undefined}
    className={controlStyles.popoverItem}
    onClick={() => onAction(item.value)}
  >{item.label}</button>)}</div>;
}

"use client";
import { controlStyles } from "@/components/ui/kalos-styles";
import * as React from "react";
import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/kalos-base-input";
import {
  Field,
  FieldLabel,
  FieldDescription,
  FieldError,
} from "@/components/ui/kalos-base-field";
export function KalosInput({
  label,
  hint,
  error,
  id,
  ...props
}: React.ComponentProps<typeof Input> & {
  label: string;
  hint?: string;
  error?: string;
}) {
  const autoId = React.useId();
  const fieldId = id || autoId;
  const descriptionId = `${fieldId}-description`;
  return (
    <Field data-invalid={!!error} className="gap-1.5">
      <FieldLabel htmlFor={fieldId} className={controlStyles.label}>{label}</FieldLabel>
      <Input
        {...props}
        className={cn(
          controlStyles.field,
          props.className,
        )}
        id={fieldId}
        aria-invalid={!!error}
        aria-describedby={error || hint ? descriptionId : undefined}
      />
      {error ? (
        <FieldError id={descriptionId} className="text-xs">
          {error}
        </FieldError>
      ) : hint ? (
        <FieldDescription id={descriptionId} className="text-xs">
          {hint}
        </FieldDescription>
      ) : null}
    </Field>
  );
}

import * as React from "react";
import { Input as InputPrimitive } from "@base-ui/react/input";
import { cn } from "cn";

function Input({ className, type, ...props }: React.ComponentProps<"input">) {
  return (
    <InputPrimitive
      type={type}
      data-slot="input"
      className={cn(
        "h-8 w-full min-w-0 rounded-[7px] border border-input/60 bg-card shadow-[0_1px_2px_color-mix(in_srgb,var(--foreground)_5%,transparent)] hover:border-input focus-visible:border-foreground/30 px-2.5 py-1 text-base transition-colors outline-none file:inline-flex file:h-6 file:border-0 file:bg-transparent file:text-[13px] file:font-medium file:text-foreground placeholder:text-muted-foreground disabled:pointer-events-none disabled:cursor-not-allowed disabled:bg-input/50 disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 md:text-[13px] dark:disabled:bg-input/80 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40",
        className,
      )}
      {...props}
    />
  );
}

export { Input };

"use client";

import { useMemo } from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";

import { Label } from "@/components/ui/kalos-base-label";
import { Separator } from "@/components/ui/kalos-base-separator";

function FieldSet({ className, ...props }: React.ComponentProps<"fieldset">) {
  return (
    <fieldset
      data-slot="field-set"
      className={cn(
        "flex flex-col gap-4 has-[>[data-slot=checkbox-group]]:gap-3 has-[>[data-slot=radio-group]]:gap-3",
        className,
      )}
      {...props}
    />
  );
}

function FieldLegend({
  className,
  variant = "legend",
  ...props
}: React.ComponentProps<"legend"> & { variant?: "legend" | "label" }) {
  return (
    <legend
      data-slot="field-legend"
      data-variant={variant}
      className={cn(
        "mb-1.5 font-medium data-[variant=label]:text-[13px] data-[variant=legend]:text-base",
        className,
      )}
      {...props}
    />
  );
}

function FieldGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-group"
      className={cn(
        "group/field-group @container/field-group flex w-full flex-col gap-5 data-[slot=checkbox-group]:gap-3 *:data-[slot=field-group]:gap-4",
        className,
      )}
      {...props}
    />
  );
}

const fieldVariants = cva(
  "group/field flex w-full gap-2 data-[invalid=true]:text-destructive",
  {
    variants: {
      orientation: {
        vertical: "flex-col *:w-full [&>.sr-only]:w-auto",
        horizontal:
          "flex-row items-center has-[>[data-slot=field-content]]:items-start *:data-[slot=field-label]:flex-auto has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px",
        responsive:
          "flex-col *:w-full @md/field-group:flex-row @md/field-group:items-center @md/field-group:*:w-auto @md/field-group:has-[>[data-slot=field-content]]:items-start @md/field-group:*:data-[slot=field-label]:flex-auto [&>.sr-only]:w-auto @md/field-group:has-[>[data-slot=field-content]]:[&>[role=checkbox],[role=radio]]:mt-px",
      },
    },
    defaultVariants: {
      orientation: "vertical",
    },
  },
);

function Field({
  className,
  orientation = "vertical",
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof fieldVariants>) {
  return (
    <div
      role="group"
      data-slot="field"
      data-orientation={orientation}
      className={cn(fieldVariants({ orientation }), className)}
      {...props}
    />
  );
}

function FieldContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-content"
      className={cn(
        "group/field-content flex flex-1 flex-col gap-0.5 leading-snug",
        className,
      )}
      {...props}
    />
  );
}

function FieldLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      data-slot="field-label"
      className={cn(
        "group/field-label peer/field-label flex w-fit gap-2 leading-snug group-data-[disabled=true]/field:opacity-50 has-data-checked:border-primary/30 has-data-checked:bg-primary/5 has-[>[data-slot=field]]:rounded-lg has-[>[data-slot=field]]:border has-[>[data-slot=field]]:not-has-[:disabled,[data-disabled]]:hover:bg-muted/50 *:data-[slot=field]:p-2.5 dark:has-data-checked:border-primary/20 dark:has-data-checked:bg-primary/10",
        "has-[>[data-slot=field]]:w-full has-[>[data-slot=field]]:flex-col",
        className,
      )}
      {...props}
    />
  );
}

function FieldTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="field-label"
      className={cn(
        "flex w-fit items-center gap-2 text-[13px] font-medium group-data-[disabled=true]/field:opacity-50",
        className,
